import SwiftUI
import SwiftData

@main
@MainActor
struct STOPAApp: App {
    private let container: ModelContainer?
    private let startupError: String?

    init() {
        do {
            let schema = Schema([RepairProject.self, RepairStep.self, RepairPart.self])
            let configuration = ModelConfiguration(schema: schema, cloudKitDatabase: .none)
            let store = try ModelContainer(for: schema, configurations: [configuration])
            // All edits are committed explicitly, so failed operations can roll back.
            store.mainContext.autosaveEnabled = false
            container = store
            startupError = nil
        } catch {
            container = nil
            startupError = error.localizedDescription
        }
    }

    var body: some Scene {
        WindowGroup {
            Group {
                if let container {
                    ProjectListView()
                        .modelContainer(container)
                } else {
                    ContentUnavailableView {
                        Label("Úložiště nelze otevřít", systemImage: "externaldrive.badge.exclamationmark")
                    } description: {
                        Text("Vaše data jsme nesmazali. Zavřete aplikaci a zkuste ji otevřít znovu.\n\n" + (startupError ?? "Neznámá chyba"))
                    }
                }
            }
            .tint(.orange)
            .preferredColorScheme(.dark)
        }
    }
}
